"use client"

import { useState, useEffect, useCallback } from "react"
import { MapPin, Truck, Clock, Navigation, X, RefreshCw } from "lucide-react"
import { Button } from "@/components/ui/button"

interface Rastreio {
  id: number
  placa: string
  modelo: string
  latitude: number
  longitude: number
  origem: string
  destino: string
  statusCarga: string
  previsaoChegada: string
}

export default function RastreioPage() {
  const [rastreios, setRastreios] = useState<Rastreio[]>([])
  const [selectedRastreio, setSelectedRastreio] = useState<Rastreio | null>(null)
  const [loading, setLoading] = useState(true)
  const [syncing, setSyncing] = useState(false)
  const [errorMsg, setErrorMsg] = useState<string | null>(null)

  const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8080"

  // 1. Carrega a lista inicial (FREE)
  const fetchInitialData = useCallback(async () => {
    setLoading(true)
    setErrorMsg(null)
    try {
      const token = localStorage.getItem("token")
      const res = await fetch(`${API_URL}/veiculos/meus-rastreios`, {
        headers: { "Authorization": `Bearer ${token}` }
      })
      if (res.ok) {
        const data = await res.json()
        setRastreios(data)
        if (data.length > 0 && !selectedRastreio) setSelectedRastreio(data[0])
      }
    } catch (error) {
      console.error("Erro fetch inicial:", error)
    } finally {
      setLoading(false)
    }
  }, [API_URL, selectedRastreio])

  useEffect(() => {
    fetchInitialData()
  }, [fetchInitialData])

  // 2. Sincroniza satélite (CONSUMES LIMIT)
  const handleSyncSatellite = async () => {
    setSyncing(true)
    setErrorMsg(null)
    try {
      const token = localStorage.getItem("token")
      const res = await fetch(`${API_URL}/veiculos/meus-rastreios/sync`, {
        method: "POST",
        headers: { "Authorization": `Bearer ${token}` }
      })
      
      if (res.ok) {
        const data = await res.json()
        setRastreios(data)
        if (selectedRastreio) {
          const updated = data.find((r: Rastreio) => r.id === selectedRastreio.id)
          if (updated) setSelectedRastreio(updated)
        }
      } else {
        const text = await res.text()
        if (text.includes("Limite")) {
          setErrorMsg("Limite de 2 consultas diárias atingido. Tente novamente amanhã.")
        } else {
          setErrorMsg("Erro ao sincronizar. Tente novamente mais tarde.")
        }
      }
    } catch (error) {
      console.error("Erro sync:", error)
      setErrorMsg("Erro de conexão com o servidor.")
    } finally {
      setSyncing(false)
    }
  }

  if (loading) return <div className="p-8 text-center text-muted-foreground">Localizando veículos...</div>

  if (rastreios.length === 0) {
    return (
      <div className="p-12 text-center border-2 border-dashed border-border rounded-2xl">
        <Truck className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
        <h2 className="text-xl font-bold text-foreground">Nenhuma carga vinculada</h2>
        <p className="text-muted-foreground">Não encontramos veículos registrados para o seu e-mail no momento.</p>
        <Button variant="outline" className="mt-4" onClick={() => (window.location.href = "/portal")}>
          Voltar ao Início
        </Button>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-display font-bold text-foreground">Rastreio de Cargas</h1>
          <p className="text-muted-foreground mt-1">Veja a última posição conhecida ou sincronize agora.</p>
        </div>
        
        <div className="flex flex-col items-end gap-2">
          <Button 
            onClick={handleSyncSatellite} 
            disabled={syncing}
            variant={errorMsg ? "destructive" : "default"}
            className="w-full sm:w-auto"
          >
            {syncing ? (
              <RefreshCw className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <Navigation className="h-4 w-4 mr-2" />
            )}
            {syncing ? "Sincronizando..." : "Sincronizar Satélite"}
          </Button>
          {errorMsg && (
            <p className="text-xs text-destructive font-medium flex items-center gap-1">
              <X className="h-3 w-3" /> {errorMsg}
            </p>
          )}
        </div>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* Lista de rastreios */}
        <div className="space-y-4">
          <h2 className="font-semibold text-foreground">Suas Cargas</h2>
          <div className="space-y-3">
            {rastreios.map((rastreio) => (
              <button
                key={rastreio.id}
                onClick={() => setSelectedRastreio(rastreio)}
                className={`w-full p-4 rounded-xl border text-left transition-all ${
                  selectedRastreio?.id === rastreio.id
                    ? "border-primary bg-primary/5"
                    : "border-border bg-card hover:border-primary/50"
                }`}
              >
                <div className="flex items-start justify-between mb-2">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
                      <Truck className="h-4 w-4 text-primary" />
                    </div>
                    <div>
                      <p className="font-bold text-foreground text-sm">{rastreio.placa}</p>
                      <p className="text-[10px] text-muted-foreground uppercase">{rastreio.modelo}</p>
                    </div>
                  </div>
                  <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-green-500/10 text-green-500 uppercase">
                    {rastreio.statusCarga || "ATIVA"}
                  </span>
                </div>
                <div className="text-xs text-muted-foreground space-y-1">
                  <div className="flex items-center gap-1">
                    <div className="w-1.5 h-1.5 rounded-full bg-muted-foreground/30" />
                    <span>{rastreio.origem || "Ponto A"}</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <div className="w-1.5 h-1.5 rounded-full bg-primary" />
                    <span className="text-foreground">{rastreio.destino || "Ponto B"}</span>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Mapa e Detalhes */}
        {selectedRastreio && (
          <div className="lg:col-span-2 space-y-6">
            <div className="rounded-2xl border border-border bg-card overflow-hidden shadow-sm">
              <div className="h-[450px] w-full bg-secondary/20 relative">
                {selectedRastreio.latitude && selectedRastreio.longitude ? (
                  <iframe
                    title="Mapa Rastreamento"
                    width="100%"
                    height="100%"
                    frameBorder="0"
                    scrolling="no"
                    marginHeight={0}
                    marginWidth={0}
                    src={`https://www.openstreetmap.org/export/embed.html?bbox=${selectedRastreio.longitude - 0.05},${selectedRastreio.latitude - 0.05},${selectedRastreio.longitude + 0.05},${selectedRastreio.latitude + 0.05}&layer=mapnik&marker=${selectedRastreio.latitude},${selectedRastreio.longitude}`}
                    className="absolute inset-0 z-0"
                  />
                ) : (
                  <div className="absolute inset-0 flex flex-col items-center justify-center text-muted-foreground bg-gradient-to-br from-secondary to-secondary/50">
                    <MapPin className="h-12 w-12 mb-4 opacity-50" />
                    <p className="font-medium text-foreground">Aguardando sinal do GPS</p>
                    <p className="text-sm">Tente sincronizar com o satélite para atualizar</p>
                  </div>
                )}
                
                <div className="absolute bottom-4 left-4 z-10">
                  <div className="px-4 py-3 bg-card/95 backdrop-blur-md rounded-xl border border-border shadow-2xl flex items-center gap-4">
                    <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center shadow-lg shadow-primary/20">
                      <Truck className="h-5 w-5 text-primary-foreground" />
                    </div>
                    <div>
                      <p className="text-sm font-black text-foreground">{selectedRastreio.placa}</p>
                      <p className="text-[10px] text-muted-foreground flex items-center gap-1">
                        <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
                        Sinal via GPS/Satélite
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
              <div className="p-4 rounded-xl border border-border bg-card">
                <p className="text-[10px] font-bold text-muted-foreground uppercase mb-1">Rota Atual</p>
                <div className="space-y-1">
                  <p className="text-xs font-medium text-foreground truncate">{selectedRastreio.origem || "-"}</p>
                  <p className="text-xs font-bold text-primary truncate">→ {selectedRastreio.destino || "-"}</p>
                </div>
              </div>

              <div className="p-4 rounded-xl border border-border bg-card">
                <p className="text-[10px] font-bold text-muted-foreground uppercase mb-1 flex items-center gap-1">
                  <Clock className="h-3 w-3" /> Previsão
                </p>
                <p className="text-sm font-black text-foreground">
                  {selectedRastreio.previsaoChegada?.split('T')[0] || "A definir"}
                </p>
              </div>

              <div className="p-4 rounded-xl border border-border bg-card">
                <p className="text-[10px] font-bold text-muted-foreground uppercase mb-1">Coordenadas</p>
                <p className="text-[10px] font-mono text-foreground font-bold">
                  {selectedRastreio.latitude ? `${selectedRastreio.latitude.toFixed(5)}, ${selectedRastreio.longitude.toFixed(5)}` : "Indisponível"}
                </p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
